var n=`0782-frango-a-zambeziana`;var a=`world-0782`;var t=`MZ`;var r=`eastern-africa`;var o=4;var s=142;var c={en:`Frango à Zambeziana`,ua:`Курка по-замбезійськи`};var u={en:`Frango à Zambeziana is a Mozambique classic prepared with chicken thigh, coconut milk, lemon juice, garlic. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка по-замбезійськи, страва кухні країни Мозамбік зі складниками: куряче стегно, кокосове молоко, лимонний сік, часник. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 100 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 100 хвилин.`,t:[`marinating`],m:100,i:[[`chicken-thigh`,850,`g`],[`coconut-milk`,320,`ml`],[`lemon-juice`,70,`ml`],[`garlic`,5,`clove`],[`hot-paprika`,6,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Grill over medium-high heat for about 30 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 30 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:30,i:[[`sunflower-oil`,40,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 9 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 9 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:9,i:[[`coconut-milk`,100,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var g={slug:n,id:a,country:`MZ`,region:r,servings:4,minutes:142,title:c,text:u,steps:l};export{t as country,g as default,a as id,s as minutes,r as region,o as servings,n as slug,l as steps,u as text,c as title};